tools.example:
x = (0:0.1:10)';
y = 3.5*exp(-0.4*x) + 0.5 + 0.05*randn(size(x));
[f, gof] = fit(x, y, 'exp1');
fprintf('a = %.3f, b = %.3f, R^2 = %.4f\n', f.a, f.b, gof.rsquare);
plot(f, x, y)
[f2, gof2] = fit(x, y, 'smoothingspline', 'SmoothingParam', 0.9);

ft = fittype('a*exp(-b*x)*sin(c*x + d)', ...
    'independent', 'x', 'coefficients', {'a','b','c','d'});
x = linspace(0, 5, 200)';
y = 4*exp(-0.8*x).*sin(6*x + 0.3) + 0.03*randn(200,1);
f = fit(x, y, ft, 'StartPoint', [3 1 5 0]);
plot(f, x, y)

ft2 = fittype('a*x^n', 'problem', 'n');
f2 = fit(x, abs(y)+1, ft2, 'problem', 2, 'StartPoint', 1);

opts = fitoptions('Method', 'NonlinearLeastSquares', ...
    'StartPoint', [4 0.5 6 0], ...
    'Lower', [0 0 0 -pi], 'Upper', [10 5 20 pi], ...
    'Robust', 'Bisquare', 'MaxIter', 1000);
ft = fittype('a*exp(-b*x)*sin(c*x + d)');
f = fit(x, y, ft, opts);

x = (1:20)';
y = 2*x.^2 - 3*x + 5 + randn(20,1)*4;
f = fit(x, y, 'poly2');
fprintf('%s\n', formula(f));
fprintf('p1 = %.4f, p2 = %.4f, p3 = %.4f\n', f.p1, f.p2, f.p3);
yhat = f([2.5; 7.5; 12.5]);
plot(f, x, y, 'predobs')

[X, Y] = meshgrid(linspace(-3, 3, 25));
Z = peaks(X, Y) + 0.2*randn(size(X));
[xd, yd, zd] = prepareSurfaceData(X, Y, Z);
sf = fit([xd yd], zd, 'lowess', 'Span', 0.15);
plot(sf, [xd yd], zd)
fprintf('Value at (0,0): %.4f\n', sf(0, 0));

x = single(1:100);           % row vector, single
y = reshape(rand(10, 10), 1, []);
y([3 27]) = NaN;
[xd, yd] = prepareCurveData(x, y);
fprintf('%d points kept, class %s\n', numel(xd), class(xd));
f = fit(xd, yd, 'poly1');

x = 1:20;
y = 1:15;
Z = rand(15, 20);
Z(5, 5) = NaN;
[xd, yd, zd] = prepareSurfaceData(x, y, Z);
fprintf('%d triplets\n', numel(zd));
sf = fit([xd yd], zd, 'poly22');

x = (1:50)';
y = 0.5*x + randn(50,1);
y([10 35]) = y([10 35]) + 25;        % outliers
f0 = fit(x, y, 'poly1');
resid = y - f0(x);
out = excludedata(x, y, 'indices', abs(resid) > 3*std(resid));
f1 = fit(x, y, 'poly1', 'Exclude', out);
plot(f1, x, y, out)

t = linspace(0, 4*pi, 400)';
y = sin(t) + 0.3*randn(400,1);
y(100) = 6;                       % spike
yMA = smooth(y, 25, 'moving');
yRL = smooth(t, y, 0.1, 'rloess');   % robust, ignores the spike
plot(t, y, '.', t, yMA, t, yRL, 'LineWidth', 1.5)
legend('data','moving','rloess')

t = linspace(0, 10, 200)';
pos = 0.5*9.81*t.^2 + 2*t + 0.3*randn(200,1);
f = fit(t, pos, 'poly2');
[vel, acc] = differentiate(f, t);
fprintf('Estimated acceleration: %.3f m/s^2\n', mean(acc));
plot(t, vel)

t = linspace(0, 20, 300)';
power = 100*exp(-t/8) + 5 + randn(300,1);
f = fit(t, power, 'exp1');
energy = integrate(f, t, 0);
fprintf('Total energy over 20 s: %.1f J\n', energy(end));
plot(t, energy)

x = (0:0.2:10)';
y = 2.5*exp(-0.3*x) + 0.05*randn(size(x));
f = fit(x, y, 'exp1');
ci = confint(f, 0.99);
names = coeffnames(f);
for k = 1:numel(names)
    fprintf('%s: [%.4f, %.4f]\n', names{k}, ci(1,k), ci(2,k));
end

x = (1:30)';
y = 3*x + 10 + randn(30,1)*5;
f = fit(x, y, 'poly1');
xg = linspace(0, 35, 200)';
[ciF, yF] = predint(f, xg, 0.95, 'functional', 'off');
ciO = predint(f, xg, 0.95, 'observation', 'off');
plot(x, y, 'o'); hold on
plot(xg, yF, '-', xg, ciF, 'b--', xg, ciO, 'r:')

f = fit((1:40)', (1:40)'.^1.7 + randn(40,1), 'power1');
c = coeffvalues(f);
names = coeffnames(f);
T = table(string(names), c', 'VariableNames', {'Coefficient','Value'});
disp(T)

x = (0:0.1:10)';
y = 3*sin(x) .* exp(-0.2*x) + 0.1*randn(size(x));
cftool(x, y)
